CREATE TABLE payable_balance(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,supplier_id uuid NOT NULL,original_xaf bigint NOT NULL CHECK(original_xaf>0),paid_xaf bigint NOT NULL DEFAULT 0 CHECK(paid_xaf>=0 AND paid_xaf<=original_xaf),version bigint NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,id)REFERENCES supplier_invoice(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,supplier_id)REFERENCES supplier(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,branch_id)REFERENCES branch(tenant_id,company_id,id));
INSERT INTO payable_balance(tenant_id,company_id,branch_id,id,supplier_id,original_xaf)SELECT tenant_id,company_id,branch_id,id,supplier_id,total_xaf FROM supplier_invoice;
CREATE TABLE supplier_advance(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,supplier_id uuid NOT NULL,original_xaf bigint NOT NULL CHECK(original_xaf>0),allocated_xaf bigint NOT NULL DEFAULT 0 CHECK(allocated_xaf>=0 AND allocated_xaf<=original_xaf),version bigint NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,supplier_id)REFERENCES supplier(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,branch_id)REFERENCES branch(tenant_id,company_id,id));
CREATE TABLE bank_evidence(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,business_date date NOT NULL,reference text NOT NULL CHECK(length(trim(reference))>0),direction text NOT NULL CHECK(direction IN('IN','OUT')),amount_xaf bigint NOT NULL CHECK(amount_xaf>0),status text NOT NULL CHECK(status IN('REQUESTED','APPROVED')),requested_by uuid NOT NULL,approved_by uuid,consumed_by uuid,reason text NOT NULL,version bigint NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,company_id,reference),FOREIGN KEY(tenant_id,company_id,branch_id)REFERENCES branch(tenant_id,company_id,id),CHECK(status<>'APPROVED' OR(approved_by IS NOT NULL AND approved_by<>requested_by)),CHECK(consumed_by IS NULL OR status='APPROVED'));
CREATE TABLE bank_match(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,evidence_id uuid NOT NULL,statement_reference text NOT NULL,business_date date NOT NULL,bank_xaf bigint NOT NULL CHECK(bank_xaf>=0),fee_xaf bigint NOT NULL CHECK(fee_xaf>=0),journal_id uuid,actor_id uuid NOT NULL,reason text NOT NULL,PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,company_id,evidence_id),UNIQUE(tenant_id,company_id,statement_reference),FOREIGN KEY(tenant_id,company_id,evidence_id)REFERENCES bank_evidence(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,journal_id)REFERENCES journal_entry(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,branch_id)REFERENCES branch(tenant_id,company_id,id));
CREATE TABLE settlement(tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('SUPPLIER_PAYMENT','SUPPLIER_ADVANCE','ADVANCE_ALLOCATION','BANK_RECEIPT','BANK_DEPOSIT','BANK_EXPENSE')),party_id uuid,source_id uuid,related_id uuid,bank_evidence_id uuid,cash_fact_id uuid,journal_id uuid NOT NULL,business_date date NOT NULL,amount_xaf bigint NOT NULL CHECK(amount_xaf>0),reason text NOT NULL,PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,company_id,bank_evidence_id),UNIQUE(tenant_id,company_id,cash_fact_id),FOREIGN KEY(tenant_id,company_id,bank_evidence_id)REFERENCES bank_evidence(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,cash_fact_id)REFERENCES tender_fact(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,journal_id)REFERENCES journal_entry(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,branch_id)REFERENCES branch(tenant_id,company_id,id),CHECK((kind='ADVANCE_ALLOCATION' AND bank_evidence_id IS NULL AND cash_fact_id IS NULL)OR(kind<>'ADVANCE_ALLOCATION' AND (bank_evidence_id IS NULL)<>(cash_fact_id IS NULL))));
ALTER TABLE bank_evidence ADD FOREIGN KEY(tenant_id,company_id,consumed_by)REFERENCES settlement(tenant_id,company_id,id)DEFERRABLE INITIALLY DEFERRED;
ALTER TABLE deposit_balance ADD COLUMN funding_kind text NOT NULL DEFAULT 'CASH' CHECK(funding_kind IN('CASH','BANK'));
ALTER TABLE tender_fact DROP CONSTRAINT tender_fact_kind_check;
ALTER TABLE tender_fact ADD CONSTRAINT tender_fact_kind_check CHECK(kind IN('RECEIPT','DEPOSIT','ALLOCATION','REFUND','VARIANCE','EXPENSE','SUPPLIER_PAYMENT','SUPPLIER_ADVANCE'));
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['payable_balance','supplier_advance','bank_evidence','bank_match','settlement']LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY scope_isolation ON %I USING(tenant_id=app_tenant() AND company_id=app_company() AND branch_id=app_branch())WITH CHECK(tenant_id=app_tenant() AND company_id=app_company() AND branch_id=app_branch())',t);END LOOP;END$$;
GRANT SELECT,INSERT,UPDATE ON payable_balance,supplier_advance,bank_evidence TO quincai_app;
GRANT SELECT,INSERT ON bank_match,settlement TO quincai_app;
CREATE TRIGGER bank_match_immutable BEFORE UPDATE OR DELETE ON bank_match FOR EACH ROW EXECUTE FUNCTION reject_fact_mutation();
CREATE TRIGGER settlement_immutable BEFORE UPDATE OR DELETE ON settlement FOR EACH ROW EXECUTE FUNCTION reject_fact_mutation();
CREATE FUNCTION protect_bank_evidence()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.amount_xaf<>OLD.amount_xaf OR NEW.business_date<>OLD.business_date OR NEW.reference<>OLD.reference OR NEW.direction<>OLD.direction OR NEW.requested_by<>OLD.requested_by THEN RAISE EXCEPTION 'Bank evidence identity immutable';END IF;IF OLD.status='APPROVED' AND(NEW.status<>OLD.status OR NEW.approved_by IS DISTINCT FROM OLD.approved_by)THEN RAISE EXCEPTION 'Bank approval immutable';END IF;IF OLD.consumed_by IS NOT NULL AND NEW.consumed_by IS DISTINCT FROM OLD.consumed_by THEN RAISE EXCEPTION 'Bank evidence already consumed';END IF;RETURN NEW;END$$;
CREATE TRIGGER bank_evidence_immutable BEFORE UPDATE ON bank_evidence FOR EACH ROW EXECUTE FUNCTION protect_bank_evidence();
ALTER TABLE operating_expense ADD COLUMN paid_bank_settlement_id uuid,ADD FOREIGN KEY(tenant_id,company_id,paid_bank_settlement_id)REFERENCES settlement(tenant_id,company_id,id);
DO $$ DECLARE c record;BEGIN FOR c IN SELECT conname FROM pg_constraint WHERE conrelid='operating_expense'::regclass AND contype='c' AND pg_get_constraintdef(oid)LIKE '%paid_fact_id%' LOOP EXECUTE format('ALTER TABLE operating_expense DROP CONSTRAINT %I',c.conname);END LOOP;END$$;
ALTER TABLE operating_expense ADD CONSTRAINT expense_paid_funding CHECK((status='POSTED' AND ((paid_fact_id IS NULL)<>(paid_bank_settlement_id IS NULL)))OR(status<>'POSTED' AND paid_fact_id IS NULL AND paid_bank_settlement_id IS NULL));
